import {_decorator, CCInteger, Component, Input, input, EventKeyboard, KeyCode, director, Contact2DType, Collider2D, IPhysics2DContact} from "cc";
const { ccclass, property } = _decorator;

import { Ground } from "./Ground";
import { Results } from "./Results";
import { bird } from "./Bird";
import { PipePool } from "./PipePool";
import { BirdAudio } from "./BirdAudio";

@ccclass("GameCtrl")
export class GameCtrl extends Component {
  @property({ type: Ground, tooltip: "this is ground" })
  public ground: Ground;

  @property({ type: Results, tooltip: "results go here" })
  public result: Results;

  @property({ type: bird })
  public bird: bird;

  @property({ type: PipePool })
  public pipeQueue: PipePool;

  @property({
    type: BirdAudio,
  })
  public clip: BirdAudio;

  @property({ type: CCInteger })
  public speed: number = 300;

  @property({ type: CCInteger })
  public pipeSpeed: number = 200;

  public isOver: boolean;

  onLoad() {
    this.initListener();
    this.result.resetScore();
    this.isOver = true;

    // Ensure bird collision listener is active
    const collider = this.bird.getComponent(Collider2D);
    if (collider) {
      console.log("bird collider registered!");
      collider.on(Contact2DType.BEGIN_CONTACT, this.onBeginContact, this);
    } else {
      console.error("bird collider NOT found!");
    }

    director.pause();
  }

  initListener() {
    input.on(Input.EventType.KEY_DOWN, (event) => {
      if (event.keyCode === KeyCode.ARROW_UP) {
        // UP arrow key
        if (this.isOver === true) {
          this.resetGame();
          this.bird.resetBird();
          this.startGame();
        }

        if (this.isOver === false) {
          this.bird.fly();
          this.clip.onAudioQueue(0);
        }
      }
    });
  }

  startGame() {
    this.result.hideResults();
    director.resume();
  }

  gameOver() {
    this.result.showResults();
    this.isOver = true;
    this.clip.onAudioQueue(3);
    director.pause();
  }

  resetGame() {
    this.result.resetScore();
    this.pipeQueue.reset();
    this.isOver = false;
    this.startGame();
  }

  passPipe() {
    this.result.addScore();
  }

  createPipe() {
    this.pipeQueue.addPool();
    this.clip.onAudioQueue(1);
  }

  contactGroundPipe() {
    let collider = this.bird.getComponent(Collider2D);

    if (collider) {
      collider.on(Contact2DType.BEGIN_CONTACT, this.onBeginContact, this);
    }
  }

  onBeginContact(selfCollider: Collider2D, otherCollider: Collider2D) {
    console.log("bird collided with:", otherCollider.node.name);
    this.bird.hitSomething = true;
    this.clip.onAudioQueue(2);
  }

  birdStruck() {
    this.contactGroundPipe();

    if (this.bird.hitSomething === true) {
      this.gameOver();
    }
  }

  update() {
    if (!this.isOver && this.bird.hitSomething) {
      console.log("Game over triggered!");
      this.gameOver();
    }
  }
}


